﻿using System;
using System.IO;
using System.Text;

namespace Burglar_and_Matches
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            int n = Next();
            int m = Next();

            var a = new int[m];
            var b = new int[m];
            for (int i = 0; i < m; i++)
            {
                a[i] = Next();
                b[i] = Next();
            }

            Array.Sort(b, a);

            int sum = 0;
            for (int i = m - 1; i >= 0; i--)
            {
                if (a[i] < n)
                {
                    sum += a[i]*b[i];
                    n -= a[i];
                }
                else
                {
                    sum += n*b[i];
                    break;
                }
            }

            writer.WriteLine(sum);
            writer.Flush();
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}
